parameters.query:
-- Disable FK constraints
SET session_replication_role = 'replica';

-- Truncate all prod tables
TRUNCATE TABLE ws_time_logs CASCADE;
TRUNCATE TABLE task_status_history CASCADE;
TRUNCATE TABLE ws_tasks CASCADE;
TRUNCATE TABLE ws_projects CASCADE;
TRUNCATE TABLE ws_users CASCADE;
TRUNCATE TABLE ws_departments CASCADE;
TRUNCATE TABLE ws_sync_state CASCADE;
TRUNCATE TABLE ws_sync_logs CASCADE;

-- Re-enable FK constraints
SET session_replication_role = 'origin';

SELECT 'Prod tables truncated' as message;

-- Disable FK constraints
SET session_replication_role = 'replica';

-- 1. Departments
INSERT INTO ws_departments SELECT * FROM zstg_ws_departments;

-- 2. Users
INSERT INTO ws_users SELECT * FROM zstg_ws_users;

-- 3. Projects
INSERT INTO ws_projects SELECT * FROM zstg_ws_projects;

-- 4. Tasks
INSERT INTO ws_tasks SELECT * FROM zstg_ws_tasks;

-- 5. Time Logs
INSERT INTO ws_time_logs SELECT * FROM zstg_ws_time_logs;

-- 6. Task Status History
INSERT INTO task_status_history SELECT * FROM zstg_task_status_history;

-- 7. Sync State
INSERT INTO ws_sync_state SELECT * FROM zstg_ws_sync_state;

-- Re-enable FK constraints
SET session_replication_role = 'origin';

-- Reset sequences
SELECT setval('ws_departments_id_seq', COALESCE((SELECT MAX(id) FROM ws_departments), 1));
SELECT setval('task_status_history_id_seq', COALESCE((SELECT MAX(id) FROM task_status_history), 1));

-- Return stats
SELECT 
  (SELECT COUNT(*) FROM ws_departments) as departments,
  (SELECT COUNT(*) FROM ws_users) as users,
  (SELECT COUNT(*) FROM ws_projects) as projects,
  (SELECT COUNT(*) FROM ws_tasks) as tasks,
  (SELECT COUNT(*) FROM ws_time_logs) as time_logs,
  (SELECT COUNT(*) FROM task_status_history) as status_history;

